import { createFileRoute } from '@tanstack/react-router'
import { Band } from '../components/Band'
import { PendingAction } from '../components/PendingAction'
import { BandFallback } from '../components/BandFallback'
import type { ReportSummary } from '../lib/types'
import { formatDate } from '../lib/dates'
import { devReports } from '../lib/devData'

export const Route = createFileRoute('/reports')({
  component: Reports,
})

/**
 * Reports, all of them generated by the server.
 *
 * The page offers a DOWNLOAD, never a print view rendered here. A
 * report drawn by the browser can be altered before anyone reads it —
 * a devtools edit, a stylesheet, a screenshot of a changed number — so
 * the document a society files or hands to an auditor is produced
 * server-side from the signed entries and comes down whole.
 *
 * That is why there is no "preview" here and no client-side totals:
 * both would be a second, unsigned rendering of the same figures, and
 * the moment the two disagree the product has no answer for which is
 * right.
 */
function Reports() {
  const reports = devReports()

  /*
   * Absent, and separately empty — this page had NEITHER branch.
   *
   * An empty list rendered the "Available" heading above nothing at
   * all, which reads as a rendering fault rather than an answer, and a
   * failed read rendered the same thing. Both now say which one it is,
   * because "no report has been generated yet" is an ordinary state
   * for a new society and "the list did not load" is not.
   */
  if (reports === null) {
    return (
      <BandFallback
        heading="Reports could not be loaded"
        headingId="cf-reports-absent"
        explanation="The list of reports did not load. This does not mean no reports exist — it means the list was not reached. Nothing has been generated or changed."
      />
    )
  }

  return (
    <>
      <Band>
        <h2 className="font-headline-md font-headline-md text-headline-md font-normal mt-0 mb-space-sm">
          Reports
        </h2>
        <p className="m-0 text-on-surface-variant max-w-[68ch]">
          Each report is produced from the recorded entries when you download
          it, so what you hand over is what the record says.
        </p>
      </Band>

      <Band heading="Available" headingId="cf-reports-list">
        {reports.length === 0 ? (
          <p className="m-0 text-on-surface-variant max-w-[68ch]">
            No report has been generated yet. A report is produced from the
            recorded entries at the time you download it, so one can be
            generated as soon as there are entries to report on.
          </p>
        ) : (
          <ul className="list-none m-0 p-0 flex flex-col gap-space-lg">
            {reports.map((report) => (
              <ReportRow key={report.id} report={report} />
            ))}
          </ul>
        )}
      </Band>
    </>
  )
}

function ReportRow({ report }: { readonly report: ReportSummary }) {
  return (
    <li className="flex flex-wrap items-baseline justify-between gap-space-md">
      <div className="min-w-0">
        <p className="m-0">{report.label}</p>
        <p className="m-0 font-label-code-sm text-label-code-sm text-on-surface-variant">
          {report.periodLabel}
          {report.generatedAt && (
            <>
              {' · last produced '}
              {formatDate(report.generatedAt)}
            </>
          )}
          {report.kind === 'agm' && (
            // Said here, not only inside the document: an adjusting
            // entry against a closed year must be disclosed at the AGM,
            // and the section is generated so it cannot be left out.
            <> · includes corrections to earlier years</>
          )}
        </p>
      </div>

      {/*
        THE ROW'S NAME IS PART OF THE BUTTON, not only beside it.
        Every row's button said "Download", so a screen reader moving
        through the button list heard "Download, Download, Download" and
        a voice-control user had no way to name the one they wanted.
        Reading the labels requires leaving the button list, which is
        the thing a button list exists to avoid.

        Visually hidden rather than a longer visible label: the
        qualifier would wrap the button on a phone, and the sighted
        reader already has the label on the same line.
      */}
      <PendingAction
        srSuffix={`${report.label}, ${report.periodLabel}`}
        className="min-h-11 px-space-lg border border-outline-variant rounded-sm bg-surface text-on-surface font-medium whitespace-nowrap"
      >
        Download
      </PendingAction>
    </li>
  )
}
